/*
 * A118385  Concatenation of the first through n-th members of A117819.
 * https://oeis.org/A118385
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  base, easy, nonn
 * Formula:   a(n) = concatenation of the first n terms of A117819. A117819
 *            begins 2,3,5,7,1,2,3,5,7,9,2,3,5,7,9,1,2,3,... The digits after
 *            the first four are generated by a repeat of the 6‑digit cycle
 *            1,2,3,5,7,9; after position 10 the cycle is rotated by one to
 *            2,3,5,7,9,1. The implementation follows this pa...
 * Range:     u8 n <= 3, u16 n <= 5, u32 n <= 10, u64 n <= 18, u128 n <= 18,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n == 0)
        return 0; /* undefined; return 0 */

    static const int base[6] = {1, 2, 3, 5, 7, 9};
    seq_t result = 0;

    for (idx_t i = 1; i <= n; ++i) {
        int digit;

        if (i == 1)          digit = 2;
        else if (i == 2)     digit = 3;
        else if (i == 3)     digit = 5;
        else if (i == 4)     digit = 7;
        else {
            idx_t r = (i - 5) % 6;        /* position inside the base cycle */
            if (i <= 10)                 /* initial cycle 1,2,3,5,7,9 */
                digit = base[r];
            else                         /* subsequent cycles rotated by one */
                digit = base[(r + 1) % 6];
        }

        result = result * 10 + (seq_t)digit;
    }

    return result;
}
